-- Added for experimental Firebird support (2026-10-18); see MODIFICATIONS.md.
-- Run only in a new disposable Firebird 3 database with default character set UTF8.
-- This fixture contains no database path, connection command, or destructive cleanup.

CREATE TABLE "CatalogParent" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "tenant" INTEGER NOT NULL,
    "externalId" BIGINT NOT NULL,
    "amount" DECIMAL(18, 6) DEFAULT 123456789012.123456,
    "numericValue" NUMERIC(9, 2),
    "title" VARCHAR(42) CHARACTER SET UTF8 DEFAULT 'it''s a value  ',
    "active" BOOLEAN DEFAULT TRUE NOT NULL,
    "createdAt" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "day" DATE,
    "clock" TIME,
    "notes" BLOB SUB_TYPE TEXT CHARACTER SET UTF8,
    "payload" BLOB SUB_TYPE BINARY,
    CONSTRAINT "PK_CatalogParent" PRIMARY KEY ("id"),
    CONSTRAINT "UQ_CatalogParent" UNIQUE ("tenant", "externalId"),
    CONSTRAINT "CK_CatalogParent" CHECK ("tenant" > 0)
);

CREATE TABLE "CatalogChild" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
    "tenant" INTEGER NOT NULL,
    "parentExternalId" BIGINT NOT NULL,
    "fixedText" CHAR(7) CHARACTER SET UTF8,
    "singleFloat" FLOAT,
    "doubleFloat" DOUBLE PRECISION,
    "smallNumber" SMALLINT,
    CONSTRAINT "PK_CatalogChild" PRIMARY KEY ("id"),
    CONSTRAINT "FK_CatalogChild" FOREIGN KEY ("tenant", "parentExternalId")
        REFERENCES "CatalogParent" ("tenant", "externalId") ON DELETE CASCADE ON UPDATE NO ACTION
);

CREATE DESCENDING INDEX "IDX_CatalogChild" ON "CatalogChild" ("tenant", "parentExternalId");
CREATE UNIQUE INDEX "IDX_CatalogTitle" ON "CatalogParent" ("title");

CREATE SEQUENCE "LegacySequence";
CREATE TABLE "CatalogLegacy" (
    "id" INTEGER NOT NULL,
    "label" VARCHAR(20) CHARACTER SET UTF8,
    CONSTRAINT "PK_CatalogLegacy" PRIMARY KEY ("id")
);

CREATE TRIGGER "BI_CatalogLegacy" FOR "CatalogLegacy"
ACTIVE BEFORE INSERT POSITION 0
AS
BEGIN
    IF (NEW."id" IS NULL) THEN
        NEW."id" = NEXT VALUE FOR "LegacySequence";
END;

-- Run this as a statement-aware adapter script, which keeps the trigger body
-- together. Firebird isql requires its own SET TERM wrapper around the trigger.
-- Introspection retains trigger/generator metadata, without inventing identity
-- or a DEFAULT that Firebird 3 cannot express for a sequence-backed column.
